def transform(grid):
    # Pattern stamped onto single pixels, keeping single pixels intact even if template center is 0
    R, C = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import defaultdict
    color_pixels = defaultdict(list)
    for r in range(R):
        for c in range(C):
            if grid[r][c] != 0:
                color_pixels[grid[r][c]].append((r, c))
    for col, pixels in color_pixels.items():
        multi = [p for p in pixels if any(abs(p[0]-q[0])<=2 and abs(p[1]-q[1])<=2 and p!=q for q in pixels)]
        singles = [p for p in pixels if p not in multi]
        if multi:
            min_r = min(r for r, c in multi)
            min_c = min(c for r, c in multi)
            offsets = [(r - (min_r + 1), c - (min_c + 1)) for r, c in multi]
            for sr, sc in singles:
                out[sr][sc] = 0 # In case center is 0, single pixel is cleared if template center is 0
                for dr, dc in offsets:
                    nr, nc = sr + dr, sc + dc
                    if 0 <= nr < R and 0 <= nc < C:
                        out[nr][nc] = col
    return out

def transform(grid):
    # Template stamped where single pixel is the center (sr, sc). Notice for 5, (17,14) is 0 in output!
    # Because (17, 14) was the center of hollow 3x3 box, it became 0!
    # Let's verify: input (17, 14)=5, output (17, 14)=0!
    # Yes! (16..18, 13..15) is 5 except (17, 14)=0!
    # So the template replaces the 3x3 neighborhood of the single pixel completely!
    R, C = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import defaultdict
    color_pixels = defaultdict(list)
    for r in range(R):
        for c in range(C):
            if grid[r][c] != 0:
                color_pixels[grid[r][c]].append((r, c))
    for col, pixels in color_pixels.items():
        multi = [p for p in pixels if any(abs(p[0]-q[0])<=2 and abs(p[1]-q[1])<=2 and p!=q for q in pixels)]
        singles = [p for p in pixels if p not in multi]
        if multi:
            min_r = min(r for r, c in multi)
            min_c = min(c for r, c in multi)
            # 3x3 template:
            for sr, sc in singles:
                for dr in range(-1, 2):
                    for dc in range(-1, 2):
                        tr = min_r + 1 + dr
                        tc = min_c + 1 + dc
                        nr, nc = sr + dr, sc + dc
                        if 0 <= nr < R and 0 <= nc < C:
                            out[nr][nc] = grid[tr][tc]
    return out

def transform(grid):
    # Same as direct 3x3 window copy, but only non-zero colors of template are drawn, except single pixel position is overwritten by template center
    R, C = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import defaultdict
    color_pixels = defaultdict(list)
    for r in range(R):
        for c in range(C):
            if grid[r][c] != 0:
                color_pixels[grid[r][c]].append((r, c))
    for col, pixels in color_pixels.items():
        multi = [p for p in pixels if any(abs(p[0]-q[0])<=2 and abs(p[1]-q[1])<=2 and p!=q for q in pixels)]
        singles = [p for p in pixels if p not in multi]
        if multi:
            min_r = min(r for r, c in multi)
            min_c = min(c for r, c in multi)
            for sr, sc in singles:
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        tr, tc = min_r + 1 + dr, min_c + 1 + dc
                        val = grid[tr][tc]
                        nr, nc = sr + dr, sc + dc
                        if 0 <= nr < R and 0 <= nc < C:
                            if val == col:
                                out[nr][nc] = col
                            elif dr == 0 and dc == 0:
                                out[nr][nc] = 0
    return out
